import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Identifying-incorrect-data.md","filePath":"manual-zh/Identifying-incorrect-data.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Identifying-incorrect-data.md"};function h(n,t,i,s,p,c){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h4 id="_5-2-1-识别不正确的数据" tabindex="-1">5.2.1 识别不正确的数据 <a class="header-anchor" href="#_5-2-1-识别不正确的数据" aria-label="Permalink to &quot;5.2.1 识别不正确的数据&quot;">​</a></h4><p>来自真实来源的数据很少完全没有错误。PSPP 有许多过程可用于帮助识别可能不正确的数据。</p><p><code>DESCRIPTIVES</code> 命令（见 <a href="./DESCRIPTIVES">DESCRIPTIVES</a>）用于为数据集生成简单的线性统计量。它也有助于识别数据中的潜在问题。示例文件 physiology.sav 包含对随机选择的一组健康成人进行的若干生理测量。但是，数据录入员在录入数据时犯了一些错误。以下示例说明了使用 <code>DESCRIPTIVES</code> 筛选此数据并识别错误值：</p><pre><code>PSPP&gt; get file=&#39;/usr/local/share/pspp/examples/physiology.sav&#39;.
PSPP&gt; descriptives sex, weight, height.
</code></pre><p>对于此示例，PSPP 产生以下输出：</p><table tabindex="0"><thead><tr><th></th><th>个案数</th><th>均值</th><th>标准差</th><th>最小值</th><th>最大值</th></tr></thead><tbody><tr><td>受试者性别</td><td>40</td><td>.45</td><td>.50</td><td>男</td><td>女</td></tr><tr><td>体重（公斤）</td><td>40</td><td>72.12</td><td>26.70</td><td>-55.6</td><td>92.1</td></tr><tr><td>身高（毫米）</td><td>40</td><td>1677.12</td><td>262.87</td><td>179</td><td>1903</td></tr><tr><td>有效 N（列表删除）</td><td>40</td><td></td><td></td><td></td><td></td></tr><tr><td>缺失 N（列表删除）</td><td>0</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>输出中最有趣的列是最小值。<strong>weight</strong> 变量的最小值为小于零，这显然是错误的。同样，<strong>height</strong> 变量的最小值似乎非常低。事实上，它距离均值超过 5 个标准差，对于成年人来说是一个看似奇怪的身高。</p><p>我们可以通过发出额外的 <code>EXAMINE</code> 命令来更深入地研究这些差异：</p><pre><code>PSPP&gt; examine height, weight /statistics=extreme(3).
</code></pre><p>此命令产生以下额外输出（部分）：</p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>个案编号</th><th>值</th></tr></thead><tbody><tr><td>身高（毫米）</td><td>最高</td><td>1</td><td>14</td><td>1903</td></tr><tr><td>2</td><td>15</td><td>1884</td><td></td><td></td></tr><tr><td>3</td><td>12</td><td>1802</td><td></td><td></td></tr><tr><td>最低</td><td>1</td><td>30</td><td>179</td><td></td></tr><tr><td>2</td><td>31</td><td>1598</td><td></td><td></td></tr><tr><td>3</td><td>28</td><td>1601</td><td></td><td></td></tr><tr><td>体重（公斤）</td><td>最高</td><td>1</td><td>13</td><td>92.1</td></tr><tr><td>2</td><td>5</td><td>92.1</td><td></td><td></td></tr><tr><td>3</td><td>17</td><td>91.7</td><td></td><td></td></tr><tr><td>最低</td><td>1</td><td>38</td><td>-55.6</td><td></td></tr><tr><td>2</td><td>39</td><td>54.5</td><td></td><td></td></tr><tr><td>3</td><td>33</td><td>55.4</td><td></td><td></td></tr></tbody></table><p>从这一新输出中，您可以看到 <strong>height</strong> 的最低值为 179（我们怀疑其是错误的），但第二低值为 1598，我们从 <code>DESCRIPTIVES</code> 中知道它在均值的一个标准差之内。同样，<strong>weight</strong> 的最低值为负，但其第二低值是合理的。这表明两个极端值是离群值，可能代表数据录入错误。</p><p>输出还标识了每个极端值的个案编号，因此我们可以看到个案 30 和 38 是具有错误值的个案。</p>`,13)])])}const P=d(o,[["render",h]]);export{l as __pageData,P as default};
